 summary['documentation_erratum']=json.loads((DATA/'native-documentation-erratum.json').read_text());write(PUBLIC/'summary.json',summary);write(PUBLIC/'confirmation-summary.json',confirmation);write(PUBLIC/'supplementary-review.json',{'v9':v9,'changes':changes,'guard_diagnostic':diag,'frozen_selection_sha256_unchanged':selection_sha});write(PUBLIC/'fixed-control-error-analysis.json',json.loads((DATA/'fixed-control-error-analysis.json').read_text()));write(PUBLIC/'documentation-erratum.json',summary['documentation_erratum']);write(PUBLIC/'confirmation-scope-amendment.json',json.loads((DATA/'confirmation-scope-amendment.json').read_text()))
 labels=['qwen_base','fixedSFT256','A1','A2'];names=['Original','Fixed SFT256','ABA A1','ABA A2'];colors=['#98a2b3','#2e90fa','#f79009','#12b76a'];fig,axes=plt.subplots(1,2,figsize=(10.8,4.6));fig.suptitle('Post-selection internal confirmation: 384 tasks / 197 groups',fontsize=13)
 lower=[confirmation['behavior'][l]['confirmed_utility_points'] for l in labels];upper=[confirmation['behavior'][l]['unresolved_upper_points'] for l in labels];axes[0].bar(range(4),lower,color=colors);axes[0].bar(range(4),[b-a for a,b in zip(lower,upper)],bottom=lower,facecolor='none',edgecolor='#667085',hatch='///');axes[0].set_title('Full-style V9 confirmed group utility');axes[0].set_ylim(0,112)
